using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
namespace CampaignDemo.Editor {
 public static class FiveFixesVerification {
  static int checks;static string report="";
  static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;report+="PASS "+label+"\n";}
  static void Near(float value,float expected,string label){Check(Mathf.Abs(value-expected)<.002f,label+" ("+value+")");}
  sealed class Fixture:IDisposable {
   public GameObject root;public BattleWorld world;public CampaignRuntime campaign;public CampaignRules rules;public readonly List<UnityEngine.Object> data=new List<UnityEngine.Object>();
   public Fixture(){root=new GameObject("Five fixes");world=root.AddComponent<BattleWorld>();world.units=Array.Empty<BattleUnit>();world.points=Array.Empty<RecoveryPoint>();rules=ScriptableObject.CreateInstance<CampaignRules>();data.Add(rules);campaign=root.AddComponent<CampaignRuntime>();campaign.world=world;campaign.rules=rules;world.campaign=campaign;campaign.combined=root.AddComponent<CombinedArmsWorld>();campaign.combined.world=world;}
   public BattleUnit Unit(string id,Vector3 at,string owner="B",float attack=.1f){var g=new GameObject(id);g.transform.SetParent(root.transform);g.transform.position=at;var unit=g.AddComponent<BattleUnit>();unit.unitId=id;unit.ownerId=owner;unit.combatDefinition=ScriptableObject.CreateInstance<ArmyCombatDefinition>();data.Add(unit.combatDefinition);unit.combatDefinition.attackRadius=attack;unit.CapacityOverride=100;unit.Initialize();unit.Campaign=campaign;world.units=world.units.Concat(new[]{unit}).ToArray();return unit;}
   public Fortification Fort(Vector3 at,string owner="B",float health=1000){var g=new GameObject("fence");g.transform.SetParent(root.transform);g.transform.position=at;var fort=g.AddComponent<Fortification>();fort.ownerId=owner;fort.radius=.05f;fort.Initialize(rules);fort.SetLineHealth(health);campaign.combined.fortifications.Add(fort);return fort;}
   public void Dispose(){UnityEngine.Object.DestroyImmediate(root);foreach(var o in data)if(o!=null)UnityEngine.Object.DestroyImmediate(o);}
  }
  static RoadPoint[] Polygon(float x,float y,float w,float h)=>new[]{new RoadPoint(x,y),new RoadPoint(x+w,y),new RoadPoint(x+w,y+h),new RoadPoint(x,y+h)};
  public static void Run(){try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
   using(var f=new Fixture()){var u=f.Unit("exposed",Vector3.zero);f.campaign.Shell(Vector3.zero,1,10);Near(u.Personnel,90,"Uncovered unit takes ordinary shell damage");}
   using(var f=new Fixture()){var u=f.Unit("wide-blast",Vector3.left*.8f);f.Fort(Vector3.right*.8f);f.campaign.Shell(Vector3.zero,1,10);Near(u.Personnel,95,"Own fence anywhere in blast protects affected unit outside its attack range");}
   using(var f=new Fixture()){var u=f.Unit("attack-range",Vector3.zero,attack:1);var fort=f.Fort(Vector3.right*.7f);f.campaign.Shell(Vector3.zero,.2f,10);Near(u.Personnel,95,"Own fence inside victim attack range protects without being struck");Near(fort.Health,1000,"Fence outside blast receives no impact damage");}
   using(var f=new Fixture()){var u=f.Unit("hostile-fence",Vector3.zero,attack:1);f.Fort(Vector3.right*.1f,"A");f.campaign.Shell(Vector3.zero,1,10);Near(u.Personnel,90,"Enemy fence grants no protection through either condition");}
   using(var f=new Fixture()){var u=f.Unit("far-fence",Vector3.zero);f.Fort(Vector3.right*2);f.campaign.Shell(Vector3.zero,.2f,10);Near(u.Personnel,90,"Fence beyond both ranges grants no protection");}
   using(var f=new Fixture()){var u=f.Unit("stacking",Vector3.zero);f.Fort(Vector3.left*.1f);f.Fort(Vector3.right*.1f);f.campaign.Shell(Vector3.zero,1,10);Near(u.Personnel,95,"Multiple fences do not stack damage reduction");}
   using(var f=new Fixture()){var u=f.Unit("outside",Vector3.right*2,attack:4);f.Fort(Vector3.zero);f.campaign.Shell(Vector3.zero,.2f,10);Near(u.Personnel,100,"Units outside blast are never damaged");}
   using(var f=new Fixture()){var u=f.Unit("destroyed",Vector3.zero);f.Fort(Vector3.zero,health:1);f.campaign.Shell(Vector3.zero,1,10);Near(u.Personnel,95,"Fence destroyed by hit still protects that impact");f.campaign.Shell(Vector3.zero,1,10);Near(u.Personnel,85,"Destroyed fence does not protect subsequent impacts");}
   using(var f=new Fixture()){var u=f.Unit("barrage",Vector3.zero);f.Fort(Vector3.zero,health:10000);var limits=new Dictionary<BattleUnit,float>();for(int i=0;i<10;i++)f.campaign.Shell(Vector3.zero,1,1000,null,null,limits);Near(u.Personnel,92.5f,"Complete barrage casualty cap also receives fifty percent reduction");}
   using(var f=new Fixture()){var blue=f.Unit("blue",Vector3.zero,"A");var red=f.Unit("red",Vector3.zero,"B");var fort=f.Fort(Vector3.zero,"A");Near(f.campaign.MovementMultiplier(blue,Vector3.left,Vector3.right),1,"Own fence never slows movement");Near(f.campaign.MovementMultiplier(red,Vector3.left,Vector3.right),.5f,"Enemy fence retains configured movement penalty");fort.Demolish();Near(f.campaign.MovementMultiplier(red,Vector3.left,Vector3.right),1,"Destroyed fence slows nobody");}
   using(var f=new Fixture()){var selection=f.root.AddComponent<ArmySelection>();selection.settings=ScriptableObject.CreateInstance<RoadMarchSettings>();f.data.Add(selection.settings);var camera=new GameObject("selection camera").AddComponent<Camera>();camera.transform.SetParent(f.root.transform);camera.transform.position=new Vector3(0,0,-10);camera.orthographic=true;camera.orthographicSize=5;camera.pixelRect=new Rect(0,0,800,600);selection.mapCamera=camera;var blue=f.Unit("box-a",Vector3.left,"A");var other=f.Unit("box-b",Vector3.right,"A");var red=f.Unit("box-enemy",Vector3.zero,"B");selection.armies=new[]{blue.gameObject.AddComponent<ArmyRoadMover>(),other.gameObject.AddComponent<ArmyRoadMover>(),red.gameObject.AddComponent<ArmyRoadMover>()};selection.CompleteRightGesture(Vector2.zero,new Vector2(800,600),true);Check(selection.HasBoxSelection&&selection.SelectedArmies.Count==2,"Right-drag completion retains multiple selected friendly units");Check(selection.SelectedArmies.All(a=>a.GetComponent<BattleUnit>().ownerId=="A"),"Right box excludes enemy units");}
   foreach(var owner in new[]{"A","B"}){var sprite=StaffMapSymbols.Depot(owner);var colors=sprite.texture.GetPixels();var fill=owner=="A"?StaffMapStyle.BlueFill:StaffMapStyle.RedFill;Check(colors.Any(c=>Vector4.Distance(c,fill)<.01f)&&colors.Any(c=>Vector4.Distance(c,StaffMapStyle.Ink)<.01f),"Depot has faction fill with black linework: "+owner);}
   using(var f=new Fixture()){var g=new GameObject("depot");g.transform.SetParent(f.root.transform);var depot=g.AddComponent<ResourceDepot>();g.AddComponent<SpriteRenderer>();depot.ownerId="A";depot.RefreshAppearance();var a=g.GetComponent<SpriteRenderer>().sprite;depot.ownerId="B";Check(g.GetComponent<SpriteRenderer>().sprite!=a&&g.GetComponent<SpriteRenderer>().color==Color.white,"Depot appearance updates immediately when captured or replicated");}
   GeometryChecks();CacheChecks();global::ShellBudgetVerification.Validate();Check(true,"Existing shell damage budget regression cases remain valid under updated cover rule");File.WriteAllText("five-fixes-verification.txt",checks+" checks passed\n"+report);EditorApplication.Exit(0);
  }catch(Exception e){File.WriteAllText("five-fixes-verification.txt","FAIL\n"+report+e);Debug.LogException(e);EditorApplication.Exit(1);}}
  static void GeometryChecks(){var random=new System.Random(57);var modern=new TerrainGeometry{Min=new RoadPoint(-10,-10),Max=new RoadPoint(10,10),DefaultTerrain=TerrainKind.Ground,roadsOverrideWater=true};var old=new LegacyTerrainGeometry{Min=modern.Min,Max=modern.Max,DefaultTerrain=modern.DefaultTerrain,roadsOverrideWater=true};var regions=new List<TerrainGeometry.Region>();for(int i=0;i<160;i++){float x=(float)random.NextDouble()*20-10,y=(float)random.NextDouble()*20-10;regions.Add(new TerrainGeometry.Region{Kind=i%3==0?TerrainKind.Water:i%3==1?TerrainKind.Forest:TerrainKind.Mountain,Polygon=Polygon(x,y,.015f+(float)random.NextDouble(),.015f+(float)random.NextDouble())});}modern.Regions=regions.ToArray();old.Regions=regions.Select(r=>new LegacyTerrainGeometry.Region{Kind=r.Kind,Polygon=r.Polygon}).ToArray();var roads=new[]{new TerrainGeometry.Region{Kind=TerrainKind.Road,Polygon=Polygon(-10,-.04f,20,.08f)}};modern.SetAutomaticRoads(roads);old.SetAutomaticRoads(roads.Select(r=>new LegacyTerrainGeometry.Region{Kind=r.Kind,Polygon=r.Polygon}).ToArray());for(int i=0;i<800;i++){var a=new RoadPoint(random.NextDouble()*20-10,random.NextDouble()*20-10);var b=i%2==0?new RoadPoint(a.X+random.NextDouble()*.4-.2,a.Y+random.NextDouble()*.4-.2):new RoadPoint(random.NextDouble()*20-10,random.NextDouble()*20-10);var access=i%3==0?TerrainAccess.All:TerrainAccess.Ground|TerrainAccess.Road|TerrainAccess.Forest;Check(modern.CanTraverse(a,b,access)==old.CanTraverse(a,b,access),"Indexed geometry preserves original thin-obstacle and road result "+i);}}
  static void CacheChecks(){var g=new GameObject("navigation cache");var map=g.AddComponent<FreeMarchMapRuntime>();map.automaticRoadTerrain=false;var def=ScriptableObject.CreateInstance<FreeMarchMapDefinition>();def.bounds=new Rect(-4,-2,8,4);map.definition=def;var access=TerrainAccess.Ground|TerrainAccess.Road;var a=new Vector3(-3,0);var b=new Vector3(3,0);Check(LocalRoadAStar.Plan(map,access,a,b,.2f,10000)!=null,"Navigation cache creates route on open terrain");def.regions=new[]{new FreeMarchMapDefinition.Region{terrain=TerrainKind.Water,polygon=new[]{new Vector2(-.3f,-2),new Vector2(.3f,-2),new Vector2(.3f,2),new Vector2(-.3f,2)}}};def.MarkDirty();Check(LocalRoadAStar.Plan(map,access,a,b,.2f,10000)==null,"Terrain revisions invalidate cached passable edges");Check(LocalRoadAStar.Plan(map,access|TerrainAccess.Water,a,b,.2f,10000)!=null,"Different terrain permissions use independent navigation cache");var water=g.AddComponent<RasterWaterMap>();var texture=new Texture2D(8,4);var pixels=Enumerable.Repeat(Color.white,32).ToArray();for(int y=0;y<4;y++)pixels[y*8+4]=new Color(.1f,.5f,.9f);texture.SetPixels(pixels);texture.Apply();water.source=texture;water.localBounds=def.bounds;map.waterMap=water;def.regions=Array.Empty<FreeMarchMapDefinition.Region>();def.MarkDirty();water.bridges=new[]{new Rect(-.1f,-2,1.2f,4)};Check(LocalRoadAStar.Plan(map,access,a,b,.2f,10000)!=null,"Cached road can use raster bridge");water.bridges=Array.Empty<Rect>();Check(LocalRoadAStar.Plan(map,access,a,b,.2f,10000)==null,"Removing raster bridge invalidates cached route edges");UnityEngine.Object.DestroyImmediate(g);UnityEngine.Object.DestroyImmediate(def);UnityEngine.Object.DestroyImmediate(texture);}
 }
}
